using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>
/// Exercises the real HTTP wire format the provider's REST API expects, and the two
/// shapes it answers with: a 200 decision body, and an outright 402 refusal.
/// </summary>
public sealed class HttpPaymentGatewayTests
{
    [Fact]
    public async Task Sends_the_reference_amount_and_currency_the_provider_expects()
    {
        var handler = new RecordingHandler(HttpStatusCode.OK, """{"status":"approved"}""");
        var sut = new Infrastructure.HttpPaymentGateway(CreateClient(handler));

        await sut.AuthorizeAsync("ORD-1", new Money(42.50m, "eur"), CancellationToken.None);

        Assert.Equal(HttpMethod.Post, handler.SentRequest!.Method);
        Assert.Equal("/v1/authorizations", handler.SentRequest.RequestUri!.AbsolutePath);

        var sentBody = JsonDocument.Parse(handler.SentBody!).RootElement;
        Assert.Equal("ORD-1", sentBody.GetProperty("reference").GetString());
        Assert.Equal(42.50m, sentBody.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", sentBody.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_response_is_read_back_as_approved()
    {
        var handler = new RecordingHandler(HttpStatusCode.OK, """{"status":"approved"}""");
        var sut = new Infrastructure.HttpPaymentGateway(CreateClient(handler));

        var outcome = await sut.AuthorizeAsync("ORD-1", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_response_is_read_back_as_declined()
    {
        var handler = new RecordingHandler(HttpStatusCode.OK, """{"status":"declined"}""");
        var sut = new Infrastructure.HttpPaymentGateway(CreateClient(handler));

        var outcome = await sut.AuthorizeAsync("ORD-1", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_refusal_from_the_provider_is_read_back_as_declined()
    {
        var handler = new RecordingHandler(HttpStatusCode.PaymentRequired, body: null);
        var sut = new Infrastructure.HttpPaymentGateway(CreateClient(handler));

        var outcome = await sut.AuthorizeAsync("ORD-1", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unexpected_server_error_is_not_swallowed_as_a_decline()
    {
        var handler = new RecordingHandler(HttpStatusCode.InternalServerError, body: null);
        var sut = new Infrastructure.HttpPaymentGateway(CreateClient(handler));

        await Assert.ThrowsAsync<HttpRequestException>(
            () => sut.AuthorizeAsync("ORD-1", new Money(10m, "EUR"), CancellationToken.None));
    }

    private static HttpClient CreateClient(HttpMessageHandler handler) =>
        new(handler) { BaseAddress = new Uri("https://provider.example.test") };

    /// <summary>Records the outgoing request and answers with a canned status/body, standing in for the provider.</summary>
    private sealed class RecordingHandler(HttpStatusCode statusCode, string? body) : HttpMessageHandler
    {
        public HttpRequestMessage? SentRequest { get; private set; }
